  const key = req.get("Idempotency-Key");
  if (!key) return res.status(400).end();
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) ON CONFLICT (account_id, idempotency_key) DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );
  if (row.sku !== req.body.sku || String(row.quantity) !== String(req.body.quantity)) return res.status(422).end();
  res.status(201).json(row);
